/*
 * Finder and Process Manager resources of the classic Mac OS (Retro68)
 * Hearts application, compiled by Rez and appended after Retro68's
 * application template, whose SIZE resource the one here replaces.
 *
 * icons.r is generated by make-icons.py from icons/sizes.
 */

#include "Processes.r"
#include "Finder.r"
#include "MacTypes.r"

#include "icons.r"

/*
 * wxWidgets needs a much bigger partition than Retro68's 1 MB default. On
 * 68k the code segments (about 11 MB with wxWidgets) are loaded into the
 * partition; on PowerPC, with virtual memory off, the whole code fragment
 * (about 20 MB) is. On top of that the game keeps a 540x600 backbuffer and
 * a bitmap per card face. The PowerPC values are also the fat application's.
 * The Finder's Get Info window can change either.
 */
#ifndef HEARTS_PREFERRED_SIZE
#  ifdef HEARTS_PPC
#    define HEARTS_PREFERRED_SIZE (32 * 1024 * 1024)
#    define HEARTS_MINIMUM_SIZE   (26 * 1024 * 1024)
#  else
#    define HEARTS_PREFERRED_SIZE (20 * 1024 * 1024)
#    define HEARTS_MINIMUM_SIZE   (15 * 1024 * 1024)
#  endif
#endif
resource 'SIZE' (-1) {
    reserved,
    acceptSuspendResumeEvents,
    reserved,
    canBackground,
    doesActivateOnFGSwitch,
    backgroundAndForeground,
    dontGetFrontClicks,
    ignoreChildDiedEvents,
    is32BitCompatible,
    isHighLevelEventAware,
    onlyLocalHLEvents,
    notStationeryAware,
    dontUseTextEditServices,
    reserved,
    reserved,
    reserved,
    HEARTS_PREFERRED_SIZE,
    HEARTS_MINIMUM_SIZE
};

resource 'vers' (1) {
    0x01, 0x00, release, 0x00,
    verUS,
    "1.0",
    "1.0, wxWidgets port of Microsoft Hearts"
};

resource 'vers' (2) {
    0x01, 0x00, release, 0x00,
    verUS,
    "1.0",
    "Hearts 1.0"
};

/* The owner (signature) resource of the 'WXHR' creator. */
type 'WXHR' as 'STR ';

resource 'WXHR' (0, "Owner resource") {
    "Hearts 1.0"
};

resource 'BNDL' (128) {
    'WXHR', 0,
    {
        'ICN#', { 0, 128 };
        'FREF', { 0, 128 }
    }
};

resource 'FREF' (128) { 'APPL', 0, "" };
